using System;using System.IO;using System.Linq;using System.Xml;using BeamScheduleFormatter;
class ProfessionalReportTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
 static void Main(string[] args){var report=ProfessionalReport.FromText("CALCULATION BASIS\nL=5m\nItem | Description | Quantity | Unit\nA | Concrete <sample> | 12.5 | m3\nB | Forms | 30 | m2", "Test <title>","<script>alert(1)</script>","A & B");string html=report.Html();Check(!html.Contains("<script>alert"),"Project text must be escaped");Check(html.Contains("&lt;script&gt;")&&html.Contains("A &amp; B"),"Escaped values retained");Check(html.Contains("12.5")&&html.Contains("30"),"Numerical records retained");Check(html.Contains("<thead>")&&html.Contains("@page"),"Tables and print pagination present");Check(!html.Contains("http://")&&!html.Contains("https://"),"Generic report self-contained");Check(html.Split(new[]{"<table class='data'>"},StringSplitOptions.None).Length==2,"Contiguous records share a real table");
  if(args.Length>0){var xml=new XmlDocument{XmlResolver=null};xml.Load(args[0]);var terrain=WindTerrainXml.Read(xml.DocumentElement);var building=new WindBuildingInput{Width=12,Length=20,Eave=3,Apex=4,AutoG=false,System="MRF Concrete"};var sample=WindReportFile.Create(terrain.Lat,terrain.Lon,"III-V",10,.85,terrain,false,building,"DEMONSTRATION — not a project design","Manila, Philippines · sample coordinates");sample.Status="DEMONSTRATION / REVIEW COPY";sample.Subtitle="Professional engineering report sample · numerical terrain snapshot, not a site-specific design approval";string wind=sample.Html();Check(wind.Contains("Surface pressures")&&wind.Contains("Example substitution"),"Pressure tables and numerical substitution present");Check(wind.Contains("<svg")&&wind.Contains("PROJECT SITE"),"Vector site and terrain figures present");Check(wind.Contains("terrain review")||wind.Contains("require review"),"Preliminary-data review notes retained");Directory.CreateDirectory(args[1]);File.WriteAllText(Path.Combine(args[1],"DTCE-Engineering-Report-Sample-v1.4.43.html"),wind);}
  Console.WriteLine("PASS: "+checks+" report escaping, structured data, print layout and wind figure checks");
 }
}
